 mbmi -> ref_frame [ 0 ] = INTRA_FRAME ;
 mbmi -> ref_frame [ 1 ] = NONE ;
 switch ( bsize ) {
 case BLOCK_4X4 : for ( i = 0 ;
 i < 4 ;
 ++ i ) mi -> bmi [ i ] . as_mode = read_intra_mode ( r , get_y_mode_probs ( mi , above_mi , left_mi , i ) ) ;
 mbmi -> mode = mi -> bmi [ 3 ] . as_mode ;
 break ;
