 is_555 = is_rle && get_bits1 ( & gb ) ;
 if ( c -> slice_split > 0 ) ctx -> split_position = c -> slice_split ;
 else if ( c -> slice_split < 0 ) {
 if ( get_bits1 ( & gb ) ) {
 if ( get_bits1 ( & gb ) ) {
 if ( get_bits1 ( & gb ) ) ctx -> split_position = get_bits ( & gb , 16 ) ;
 else ctx -> split_position = get_bits ( & gb , 12 ) ;
 }
