 }
 }
 else ctx -> split_position = avctx -> height ;
 if ( c -> slice_split && ( ctx -> split_position < 1 - is_555 || ctx -> split_position > avctx -> height - 1 ) ) return AVERROR_INVALIDDATA ;
 align_get_bits ( & gb ) ;
 buf += get_bits_count ( & gb ) >> 3 ;
